import { Ui } from "foldkit";

export const { descriptionId } = Ui.Input;
export const { view } = Ui.Input;

export type InputAttributes<ParentMessage> =
  Ui.Input.InputAttributes<ParentMessage>;
export type ViewConfig<ParentMessage> = Ui.Input.ViewConfig<ParentMessage>;

export {
  descriptionClassName,
  fieldClassName,
  inputClassName,
  labelClassName,
} from "./view";

export const inputClassName =
  "block w-full rounded-lg border border-gray-300 bg-white px-3 py-2 text-base text-gray-900 transition-colors placeholder:text-gray-400 focus:border-accent-500 focus:outline-none focus:ring-1 focus:ring-accent-500 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const labelClassName = "block text-sm font-medium text-gray-700";

export const descriptionClassName = "text-sm text-gray-500";

export const fieldClassName = "flex w-full max-w-sm flex-col gap-1.5";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, test } from "vitest";

import * as Input from "./index";

const UpdatedName = m("UpdatedName", { value: S.String });

interface Model {
  readonly value: string;
}

type Message = typeof UpdatedName.Type;

const initialModel: Model = { value: "" };

const update = (model: Model, message: Message): readonly [Model, []] => [
  { value: message.value },
  [],
];

const view = (model: Model): Html => {
  const h = html<Message>();

  return Input.view<Message>({
    id: "name-input",
    value: model.value,
    placeholder: "Enter your full name",
    onInput: (value) => UpdatedName({ value }),
    toView: (attributes) =>
      h.div(
        [h.Class(Input.fieldClassName)],
        [
          h.label(
            [...attributes.label, h.Class(Input.labelClassName)],
            ["Name"]
          ),
          h.input([...attributes.input, h.Class(Input.inputClassName)]),
          h.p(
            [...attributes.description, h.Class(Input.descriptionClassName)],
            ["As it appears on your government-issued ID."]
          ),
        ]
      ),
  });
};

const disabledView = (): Html => {
  const h = html<Message>();

  return Input.view<Message>({
    id: "disabled-name-input",
    value: "Ada Lovelace",
    isDisabled: true,
    toView: (attributes) =>
      h.div(
        [h.Class(Input.fieldClassName)],
        [
          h.label(
            [...attributes.label, h.Class(Input.labelClassName)],
            ["Disabled name"]
          ),
          h.input([...attributes.input, h.Class(Input.inputClassName)]),
          h.p(
            [...attributes.description, h.Class(Input.descriptionClassName)],
            ["This input is disabled."]
          ),
        ]
      ),
  });
};

describe("Input registry view", () => {
  test("renders label, description, placeholder, and input messages", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("textbox", { name: "Name" })).toExist(),
      Scene.expect(
        Scene.text("As it appears on your government-issued ID.")
      ).toExist(),
      Scene.type(Scene.role("textbox", { name: "Name" }), "Ada Lovelace"),
      Scene.expect(Scene.role("textbox", { name: "Name" })).toHaveValue(
        "Ada Lovelace"
      )
    );
  });

  test("supports disabled native input state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("textbox", { name: "Disabled name" })
      ).toBeDisabled()
    );
  });
});
